package br.com.onda;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import androidx.media3.common.*;import androidx.media3.session.*;import androidx.media3.session.MediaController;import com.google.common.util.concurrent.ListenableFuture;import java.io.*;import java.util.*;import java.util.concurrent.TimeUnit;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class MemoryMarkTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private MainActivity anchor;private Activity extra;private MediaController player;private ListenableFuture<MediaController> connection;private final List<File> files=new ArrayList<>();private File wav;
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{for(int i=0;i<400;i++){boolean[] done={false};ins.runOnMainSync(()->{try{done[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(done[0])return;Thread.sleep(50);}fail("Manual memory marker timed out");}
 private Object field(Object target,String name)throws Exception{java.lang.reflect.Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 private void call(Object target,String name)throws Exception{java.lang.reflect.Method m=target.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(target);}
 private EditText input(View v,String label){if(v instanceof EditText&&label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return (EditText)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){EditText found=input(((ViewGroup)v).getChildAt(i),label);if(found!=null)return found;}return null;}
 @Before public void before()throws Exception{assertFalse(MemoryIndexService.running);c.deleteDatabase("multimedia-memory.db");wav=AudioTestFixtures.tone(c,30000);files.add(wav);anchor=(MainActivity)ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->anchor.hasWindowFocus());ins.runOnMainSync(()->connection=new MediaController.Builder(c,new SessionToken(c,new ComponentName(c,PlaybackService.class))).buildAsync());player=connection.get(15,TimeUnit.SECONDS);ins.runOnMainSync(()->{player.pause();player.setRepeatMode(Player.REPEAT_MODE_OFF);player.setMediaItem(new MediaItem.Builder().setMediaId("download:871").setUri(Uri.fromFile(wav)).setMediaMetadata(new MediaMetadata.Builder().setTitle("Faixa de teste").build()).build(),10500);player.prepare();});waitFor(()->player.getPlaybackState()==Player.STATE_READY&&field(anchor,"player")!=null&&((MediaController)field(anchor,"player")).isCurrentMediaItemSeekable());}
 @After public void after(){ins.runOnMainSync(()->{if(extra!=null)extra.finish();if(anchor!=null)anchor.finish();if(player!=null){player.pause();player.stop();player.clearMediaItems();}if(connection!=null)MediaController.releaseFuture(connection);});ins.waitForIdleSync();for(File f:files)f.delete();}
 private MemoryStore.Source manual(String kind){return MemoryStore.source(c,Uri.fromFile(wav),null,"Marcações do teste",kind);}
 @Test public void manualNotesSurviveAutomaticReindexWithoutDuplicates()throws Exception{MemoryStore.Source own=manual("manual_audio"),automatic=manual("audio");try(MemoryStore store=new MemoryStore(c)){store.replace(automatic,w->w.add(new MemoryText.Cue(0,8000,-1,"Texto reconhecido")));store.note(own,new MemoryText.Cue(1000,3000,-1,"Solo de guitarra"));store.note(own,new MemoryText.Cue(4000,6000,-1,"Introdução"));store.note(own,new MemoryText.Cue(1000,3000,-1,"Solo de guitarra"));store.replace(automatic,w->w.add(new MemoryText.Cue(0,8000,-1,"Nova transcrição")));assertEquals(1,store.search("solo guitarra",false).size());assertEquals(2,store.search("",true).size());assertEquals(2,store.sources().size());assertEquals(1,store.search("transcricao",false).size());}}
 @Test public void renameAndDeleteRefreshSearchAndFavoritesOnlyForOwnMarks()throws Exception{try(MemoryStore store=new MemoryStore(c)){MemoryStore.Source own=manual("manual_audio");store.note(own,new MemoryText.Cue(1000,3000,-1,"Solo de guitarra"));store.note(own,new MemoryText.Cue(4000,6000,-1,"Explicação"));MemoryStore.Hit old=store.search("guitarra",false).get(0);store.renameNote(old,"Solo de violino");assertTrue(store.search("guitarra",false).isEmpty());MemoryStore.Hit changed=store.search("violino",true).get(0);assertEquals(1000,changed.start);store.removeNote(changed);assertEquals(1,store.search("",true).size());assertEquals(1,store.search("explicacao",false).size());MemoryStore.Source auto=manual("audio");store.replace(auto,w->w.add(new MemoryText.Cue(0,8000,-1,"Transcrição automática")));MemoryStore.Hit hit=store.search("automatica",false).get(0);try{store.removeNote(hit);fail();}catch(IOException expected){}try{store.renameNote(hit,"Alterada");fail();}catch(IOException expected){}assertEquals(1,store.search("automatica",false).size());}}
 @Test public void changedFilesDoNotMixNewMarksWithOldOffsets()throws Exception{try(MemoryStore store=new MemoryStore(c)){MemoryStore.Source first=manual("manual_audio");store.note(first,new MemoryText.Cue(1000,3000,-1,"Original"));try(OutputStream out=new FileOutputStream(wav,true)){out.write(1);}MemoryStore.Source changed=manual("manual_audio");assertNotEquals(first.stamp,changed.stamp);try{store.note(changed,new MemoryText.Cue(4000,6000,-1,"Outra"));fail();}catch(IOException expected){}assertEquals(1,store.search("original",true).size());assertTrue(store.search("outra",false).isEmpty());}}
 @Test public void mainFormCapturesExactBoundsAndSavesWhileMusicKeepsPlaying()throws Exception{AlertDialog[] dialog={null};ins.runOnMainSync(()->{try{call(anchor,"markMemory");dialog[0]=(AlertDialog)field(anchor,"memoryDialog");}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();ins.runOnMainSync(()->{assertNotNull(dialog[0]);View root=dialog[0].getWindow().getDecorView();assertEquals("0:10.500",input(root,"Início da marcação").getText().toString());assertEquals("0:18.500",input(root,"Fim da marcação").getText().toString());input(root,"Nome da marcação na memória").setText("Solo de guitarra");player.play();});waitFor(()->player.isPlaying());capture("memory-mark-form.png");ins.runOnMainSync(()->dialog[0].getButton(AlertDialog.BUTTON_POSITIVE).performClick());waitFor(()->!dialog[0].isShowing());try(MemoryStore store=new MemoryStore(c)){MemoryStore.Hit hit=store.search("solo guitarra",true).get(0);assertEquals(10500,hit.start);assertEquals(18500,hit.end);assertEquals("manual_audio",hit.source.kind);}ins.runOnMainSync(()->{assertEquals("download:871",player.getCurrentMediaItem().mediaId);assertTrue(player.isPlaying());assertTrue(player.getCurrentPosition()>=10500);});}
 @Test public void invalidRangeAndCancelNeverSaveAnything()throws Exception{AlertDialog[] d={null};ins.runOnMainSync(()->{try{call(anchor,"markMemory");d[0]=(AlertDialog)field(anchor,"memoryDialog");}catch(Exception e){throw new RuntimeException(e);}View root=d[0].getWindow().getDecorView();input(root,"Nome da marcação na memória").setText("Inválida");input(root,"Fim da marcação").setText("0:01.000");d[0].getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertTrue(d[0].isShowing());d[0].getButton(AlertDialog.BUTTON_NEGATIVE).performClick();});ins.waitForIdleSync();waitFor(()->!d[0].isShowing());try(MemoryStore store=new MemoryStore(c)){assertTrue(store.sources().isEmpty());}ins.runOnMainSync(()->assertFalse(player.getPlayWhenReady()));}
 @Test public void videoAndPdfMenusCreateMarksWithoutSpeechModel()throws Exception{File movie=File.createTempFile("memory-mark-",".mp4",c.getCacheDir());files.add(movie);try(InputStream in=ins.getContext().getAssets().open("memory-mark-video.mp4");OutputStream out=new FileOutputStream(movie)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}extra=ins.startActivitySync(new Intent(c,VideoActivity.class).setAction(Intent.ACTION_VIEW).setDataAndType(Uri.fromFile(movie),"video/mp4").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->(boolean)field(extra,"framesSeen")&&((org.videolan.libvlc.MediaPlayer)field(extra,"video")).isSeekable());AlertDialog[] d={null};ins.runOnMainSync(()->{try{call(extra,"markMemory");d[0]=(AlertDialog)field(extra,"memoryDialog");input(d[0].getWindow().getDecorView(),"Nome da marcação na memória").setText("Cena importante");d[0].getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->!d[0].isShowing());try(MemoryStore store=new MemoryStore(c)){assertEquals("manual_video",store.search("cena",true).get(0).source.kind);}ins.runOnMainSync(()->extra.finish());ins.waitForIdleSync();File pdf=File.createTempFile("memory-mark-",".pdf",c.getCacheDir());files.add(pdf);android.graphics.pdf.PdfDocument doc=new android.graphics.pdf.PdfDocument();for(int i=0;i<2;i++){android.graphics.pdf.PdfDocument.Page p=doc.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(300,400,i+1).create());p.getCanvas().drawText("Juros compostos",20,40,new android.graphics.Paint());doc.finishPage(p);}try(OutputStream out=new FileOutputStream(pdf)){doc.writeTo(out);}doc.close();extra=ins.startActivitySync(new Intent(c,PdfActivity.class).setAction(Intent.ACTION_VIEW).setDataAndType(Uri.fromFile(pdf),"application/pdf").putExtra("onda_page",1).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->(boolean)field(extra,"ready")&&(int)field(extra,"page")==1);ins.runOnMainSync(()->{try{call(extra,"markMemory");d[0]=(AlertDialog)field(extra,"memoryDialog");View root=d[0].getWindow().getDecorView();assertNull(input(root,"Início da marcação"));input(root,"Nome da marcação na memória").setText("Capítulo de juros");d[0].getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->!d[0].isShowing());try(MemoryStore store=new MemoryStore(c)){MemoryStore.Hit hit=store.search("capitulo juros",true).get(0);assertEquals(1,hit.page);assertEquals("manual_pdf",hit.source.kind);}}
 private void capture(String name)throws Exception{ins.waitForIdleSync();Thread.sleep(250);android.graphics.Bitmap shot=ins.getUiAutomation().takeScreenshot();assertNotNull(shot);try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),name))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}}
}
